/// <summary>
/// processes the new values into InventTable and InventTableModule 
/// </summary>
private void processNewValues()
{
    Args args = new Args();
    NDXItemHK2MGKValues lNDXItemHK2MGKValues;

    lNDXItemHK2MGKValues = NDXItemHK2MGKValues_DS.getFirst(1) ? NDXItemHK2MGKValues_DS.getFirst(1) : NDXItemHK2MGKValues_DS.cursor();

    while(lNDXItemHK2MGKValues)
    {
        args.caller(this);
        args.record(lNDXItemHK2MGKValues);
        new MenuFunction(menuItemActionStr(NDXItemHK2MGKUpdateHK2MGKGroups), MenuItemType::Action).run(args);

        lNDXItemHK2MGKValues =  NDXItemHK2MGKValues_DS.getNext();
    }

    InventTable_ds.research(true);
}

